import math
from itertools import permutations

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def sigma(n):
    # Calculates the sum of divisors
    def prime_factorization(n):
        factors = {}
        d = 2
        temp = n
        while d * d <= temp:
            while temp % d == 0:
                factors[d] = factors.get(d, 0) + 1
                temp //= d
            d += 1
        if temp > 1:
            factors[temp] = factors.get(temp, 0) + 1
        return factors

    factors = prime_factorization(n)
    sum_div = 1
    for p, a in factors.items():
        sum_div *= (p**(a+1) - 1) // (p - 1)
    return sum_div

def is_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def solve_m(m):
    divisors = get_divisors(m)
    sum_div = sigma(m)
    n = len(divisors)

    if not is_square(sum_div):
        return False, None # Sum is not a square

    # Try all permutations (since N is small, this might work for m<=40)
    # However, N can be up to 8 or 9 for m<=40 (e.g., 36, 40). 9! = 362,880. This is feasible.

    for p in permutations(divisors):
        current_sum = 0
        is_valid = True
        for i in range(n):
            current_sum += p[i]
            if not is_square(current_sum):
                is_valid = False
                break

        if is_valid and current_sum == sum_div:
            return True, list(p)

    return False, None


results = {}
for m in range(2, 41):
    success, permutation = solve_m(m)
    results[m] = {
        'sigma_sq': is_square(sigma(m)),
        'success': success,
        'permutation': permutation
    }

print("--- Results Summary ---")
