import math

def sigma(n):
    """Calculates the sum of divisors function sigma(n)."""
    if n <= 0:
        return 0
    s = 1
    temp = n
    d = 2
    while d * d <= temp:
        if temp % d == 0:
            power = 0
            while temp % d == 0:
                power += 1
                temp //= d
            s *= (d**(power + 1) - 1) // (d - 1)
        d += 1
    if temp > 1:
        s *= (temp**(1 + 1) - 1) // (temp - 1)
    return s

def find_candidates(start, end):
    """Finds composite m in the range [start, end] such that sigma(m) is a perfect square."""
    candidates = []
    for m in range(start, end + 1):
        if m <= 39 or m > 100: # Focus on the required range 41 to 100
            continue

        # Check if m is composite
        is_prime = True
        for i in range(2, int(math.sqrt(m)) + 1):
            if m % i == 0:
                is_prime = False
                break
        if is_prime:
            continue

        s_m = sigma(m)

        # Check if sigma(m) is a perfect square
        sqrt_s_m = math.isqrt(s_m)
        if sqrt_s_m * sqrt_s_m == s_m:
            candidates.append(m)

    return candidates

# Run the search for m in [41, 100]
candidates = find_candidates(41, 100)
print("Candidates M:", candidates)

